<?php use Luna\Core\Csrf;use Luna\Core\View;$token=View::e(Csrf::token());?>
<div class="page-intro"><div><span class="eyebrow">Connected agenda</span><h1>Calendari sincronizzati</h1><p>Google Calendar, iCloud e CalDAV con sincronizzazione bidirezionale e log.</p></div><a class="button primary" href="/r/calendar-events/create">Nuovo evento</a></div>
<details class="card setup-panel"><summary><span class="metric-icon blue"><?= View::icon('calendar') ?></span><span><strong>Configura un account</strong><small>OAuth Google oppure endpoint CalDAV/iCloud; il segreto resta in una variabile ENV.</small></span><?= View::icon('chevron','setup-chevron') ?></summary><form method="post" action="/operations/calendar/settings" class="form-grid"><input type="hidden" name="_token" value="<?= $token ?>"><label class="field">Utente<select name="user_id"><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>"><?= View::e($u['name']) ?></option><?php endforeach;?></select></label><label class="field">Provider<select name="provider"><option>GOOGLE</option><option>ICLOUD</option><option>CALDAV</option></select></label><label class="field">Account email<input type="email" name="account_email" required></label><label class="field">Endpoint CalDAV HTTPS<input type="url" name="endpoint_url" placeholder="https://..."></label><label class="field">Autenticazione<select name="auth_type"><option>OAUTH2</option><option>APP_PASSWORD</option><option>BASIC</option><option>BEARER</option></select></label><label class="field">Riferimento segreto<input name="secret_reference" placeholder="ENV:LUNA_CALENDAR_MARIO" required></label><label class="field">ID calendario esterno<input name="external_calendar_id" placeholder="primary"></label><div class="form-actions full-width"><button class="button primary">Salva account</button></div></form></details>
<section class="card"><div class="card-header"><div><h2>Account</h2><p>I token e le app password sono letti da riferimenti ENV.</p></div></div><div class="table-wrap"><table><thead><tr><th>Persona</th><th>Provider</th><th>Account</th><th>Ultimo sync</th><th>Errore</th><th></th></tr></thead><tbody><?php foreach($accounts as $a):?><tr><td class="primary-cell"><?= View::e($a['user_name']) ?></td><td><?= View::e($a['provider']) ?></td><td><?= View::e($a['account_email']) ?></td><td><?= View::date($a['last_sync_at']) ?></td><td><?= View::e(mb_substr((string)($a['last_error']??''),0,90)) ?></td><td><form method="post" action="/operations/calendar/<?= (int)$a['id'] ?>/sync"><input type="hidden" name="_token" value="<?= $token ?>"><button class="button primary">Sincronizza</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><div class="card-header"><h2>Agenda</h2></div><div class="table-wrap"><table><thead><tr><th>Inizio</th><th>Fine</th><th>Evento</th><th>Luogo</th><th>Provider</th><th>Sync</th></tr></thead><tbody><?php foreach($events as $e):?><tr><td><?= View::date($e['starts_at']) ?></td><td><?= View::date($e['ends_at']) ?></td><td class="primary-cell"><?= View::e($e['title']) ?></td><td><?= View::e($e['location']??'—') ?></td><td><?= View::e($e['provider']) ?></td><td><span class="badge status-<?= strtolower($e['sync_status']) ?>"><?= View::e($e['sync_status']) ?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="card"><div class="card-header"><h2>Log sincronizzazioni</h2></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Account</th><th>Direzione</th><th>Elaborati</th><th>Errori</th><th>Stato</th><th>Messaggio</th></tr></thead><tbody><?php foreach($logs as $l):?><tr><td><?= View::date($l['started_at']) ?></td><td><?= View::e($l['account_email']) ?></td><td><?= View::e($l['direction']) ?></td><td><?= (int)$l['processed_count'] ?></td><td><?= (int)$l['error_count'] ?></td><td><span class="badge status-<?= strtolower($l['status']) ?>"><?= View::e($l['status']) ?></span></td><td><?= View::e($l['message']??'') ?></td></tr><?php endforeach;?></tbody></table></div></section>
